column2:
{
  "app_id" : "F-agent-nih-c43a69db-30e7",
  "app_version" : 4,
  "interaction_transcript" : [ {
    "role" : "agent",
    "en_text" : "హలో, నేను రాధను, నేను రచన సిమెంట్ ఐరన్ అండ్ హార్డ్‌వేర్‌తో మాట్లాడుతున్నానా?"
  } ]
}

{
  "app_id" : "F-agent-nih-c43a69db-30e7",
  "app_version" : 4,
  "interaction_transcript" : [ {
    "role" : "agent",
    "en_text" : "ஹலோ, நான் ராதா, நான் பாரத் ரகுவிடம் பேசுகிறேனா?"
  } ]
}

{
  "interaction_transcript": [
    {"role": "agent", "en_text": "నమస్కారం. నేను SMFG ఇండియా క్రెడిట్ కంపెనీ నుండి వాణి మాట్లాడుతున్నాను. నేను కొడిదేటి శ్రీనివాసరావుతో మాట్లాడుతున్నానా?"}
  ]
}

{
  "interaction_transcript": [
    {"role": "agent", "en_text": "नमस्कार. मी वाणी एसएमएफजी इंडिया क्रेडिट कंपनीतून बोलत आहे. मी इक्बाल मोहम्मद्जाफर बहादूर यांच्याशी बोलत आहे का?"},
    {"role": "agent", "en_text": "नमस्कार, आपण कॉलवर आहात का?"},
    {"role": "user", "en_text": "हो."},
    {"role": "agent", "en_text": "एसएमएफजी इंडिया क्रेडिट कंपनीकडून तुमचा ईएमआय अजून प्रलंबित आहे. तुमची एकूण प्रलंबित रक्कम 1,68,035 आहे आणि तुम्हाला काही लेट फीचे शुल्क देखील आहेत. कृपया तुम्ही अजूनपर्यंत पेमेंट का केले नाही हे सांगू शकाल का?"},
    {"role": "agent", "en_text": "नमस्कार, आपण कॉलवर आहात का?"},
    {"role": "agent", "en_text": "तुमच्या वेळेसाठी धन्यवाद"}
  ]
}

{
  "interaction_transcript": [
    {"role": "agent", "en_text": "नमस्ते। मैं राधा एसएमएफजी इंडिया क्रेडिट कंपनी से बात कर रही हूं। क्या मैं सुरज मोहम्मद से बोल रही हूं?"},
    {"role": "user", "en_text": "हाँ।"},
    {"role": "agent", "en_text": "सुरज मोहम्मद, एसएमएफजी इंडिया क्रेडिट कंपनी के साथ आपके लोन की ईएमआई 22,646 रुपये की अदायगी की तारीख नजदीक आ रही है। क्या आप 5 अक्टूबर 2025 से पहले अपने खाते में पर्याप्त बैलेंस रख पाएंगे?"},
    {"role": "user", "en_text": "हाँ।"},
    {"role": "agent", "en_text": "धन्यवाद सुरज मोहम्मद, आपकी समय पर भुगतान आपके रिपेमेंट रिकॉर्ड को मजबूत रखने में मदद करेगी। यदि आपको कोई और जानकारी या सहायता चाहिए, तो कृपया हमें बताएं।"},
    {"role": "user", "en_text": "नहीं सर, धन्यवाद।"},
    {"role": "agent", "en_text": "एसएमएफजी से बात करने के लिए धन्यवाद। आपका दिन शुभ हो। अलविदा"}
  ]
}

{
  "interaction_transcript": [
    {"role": "agent", "en_text": "नमस्कार, मी राधा आहे, मी अक्षयकुमारप्रकाश कांबळेशी बोलत आहे का?"},
    {"role": "user", "en_text": "हो"},
    {"role": "agent", "en_text": "अक्षयकुमारप्रकाश कांबळे, तुमचे SMFG इंडिया क्रेडिट कंपनीकडून ₹11,770 येणे बाकी आहे. हे आज भरणे शक्य आहे का?"}
  ]
}

{
  "interaction_transcript": [
    {
      "role": "agent",
      "en_text": "வணக்கம். நான் SMFG INDIA CREDIT COMPANY-யில் இருந்து ராதா பேசுகிறேன். நான் சுமதி கே-யிடம் பேசுகிறேனா?"
    },
    {
      "role": "user",
      "en_text": "ஆம்."
    },
    {
      "role": "agent",
      "en_text": "சுமதி கே, SMFG INDIA CREDIT COMPANY-யில் உங்களின் ₹10,522 கடன் EMI-யின் தவணை தேதி நெருங்குகிறது. பிப்ரவரி 4, 2026-க்குள் உங்களின் கணக்கில் போதுமான இருப்புத்தொகையை வைத்திருக்க முடியுமா?"
    },
    {
      "role": "agent",
      "en_text": "மன்னிக்கவும், உங்கள் குரல் தெளிவாக கேட்கவில்லை. மீண்டும் கூற முடியுமா?"
    },
    {
      "role": "agent",
      "en_text": "உங்கள் பொன்னான நேரத்திற்கு நன்றி. இனிய நாள் அமையட்டும்."
    }
  ]
}

{
  "app_id" : "Bucket-3-an-a76b0c20-236f",
  "app_version" : 8,
  "interaction_transcript" : [ {
    "role" : "agent",
    "en_text" : "నమస్కారం. నేను SMFG ఇండియా క్రెడిట్ కంపెనీ నుండి వాణి మాట్లాడుతున్నాను. నేను పి రాజేష్‌తో మాట్లాడుతున్నానా?"
  } ]
}

{
  "interaction_transcript": [
    {"role": "agent", "en_text": "हॅलो. मी राधा एसएमएफजी इंडिया क्रेडिट कंपनीतून बोलत आहे. मी विलास वासनिक यांच्याशी बोलत आहे का?"},
    {"role": "user", "en_text": "होय"},
    {"role": "agent", "en_text": "विलास वासनिक, एसएमएफजी इंडिया क्रेडिट कंपनीच्या तुमच्या कर्जाच्या ईएमआयची ४,३४२ रुपये रक्कम देय असलेली तारीख जवळ येत आहे. ५ ऑक्टोबर २०२५ पूर्वी तुमच्या खात्यात पुरेशी रक्कम शिल्लक ठेवू शकाल का?"},
    {"role": "user", "en_text": "आजूबाजूचे लोक इथे आहेत, हलवा. आत काही समस्या आहे, होय."},
    {"role": "agent", "en_text": "मला समजले आहे की सध्या तुम्हाला काही समस्या आहेत, पण मला तुमच्या कर्ज ईएमआय पेमेंटबद्दल चर्चा करायची आहे. विलास वासनिक, एसएमएफजी इंडिया क्रेडिट कंपनीच्या तुमच्या कर्जाच्या ईएमआयची ४,३४२ रुपये रक्कम देय असलेली तारीख जवळ येत आहे. ५ ऑक्टोबर २०२५ पूर्वी तुमच्या खात्यात पुरेशी रक्कम शिल्लक ठेवू शकाल का?"}
  ]
}

{
  "interaction_transcript": [
    {"role": "agent", "en_text": "नमस्ते। मैं राधा एसएमएफजी इंडिया क्रेडिट कंपनी से फोन कर रही हूं। क्या मैं विजय कुमार से बात कर रही हूं?"},
    {"role": "user", "en_text": "हां।"},
    {"role": "agent", "en_text": "विजय कुमार, एसएमएफजी इंडिया क्रेडिट कंपनी के साथ आपके लोन की ईएमआई 23,396 रुपये की नियत तिथि नजदीक आ रही है। क्या आप 5 अक्टूबर 2025 से पहले अपने खाते में पर्याप्त शेष राशि रख पाएंगे?"},
    {"role": "user", "en_text": "हां।"},
    {"role": "agent", "en_text": "धन्यवाद विजय कुमार, आपका समय पर भुगतान आपके चुकौती रिकॉर्ड को मजबूत रखने में मदद करेगा। यदि आपको कोई और जानकारी या सहायता चाहिए, तो कृपया हमें बताएं।"},
    {"role": "user", "en_text": "नहीं, ठीक है।"},
    {"role": "agent", "en_text": "विजय कुमार, क्या आप हमें बता सकते हैं कि आप 5 अक्टूबर 2025 को ईएमआई भुगतान क्यों नहीं कर पाएंगे? क्या कोई समस्या है?"}
  ]
}

{
  "interaction_transcript": [
    {"role": "agent", "en_text": "नमस्ते। मैं एसएमएफजी इंडिया क्रेडिट कंपनी से वाणी बोल रही हूँ। क्या मेरी बात शशिकांत मिश्रा से हो रही है?"}
  ]
}

{
  "interaction_transcript": [
    {"role": "agent", "en_text": "हेलो, मैं राधा हूँ, क्या मैं कृष्ण रायकवार से बात कर रही हूँ?"}
  ]
}

{
  "interaction_transcript": [
    {
      "role": "agent",
      "en_text": "வணக்கம். நான் ராதா பேசுகிறேன், SMFG இந்தியா நிறுவனத்திலிருந்து அழைக்கிறேன். நான் பிரேம்குமார் சந்திரசேகரன் அவர்களிடம் பேசுகிறேனா?"
    },
    {
      "role": "user",
      "en_text": "ஆம், சொல்லுங்கள்."
    },
    {
      "role": "agent",
      "en_text": "உறுதிப்படுத்தியதற்கு நன்றி. இந்த அழைப்பு உங்கள் 4573 என்று முடியும் கடன் கணக்கு எண் தொடர்பானது. உங்கள் KYC விவரங்களை புதுப்பிப்பது குறித்து இந்த அழைப்பு செய்யப்படுகிறது. சரிபார்ப்பைத் தொடரலாமா?"
    },
    {
      "role": "user",
      "en_text": "இல்லை, இல்லை, இல்லை."
    },
    {
      "role": "agent",
      "en_text": "நீங்கள் வேலையாக இருக்கலாம் என்று எனக்குப் புரிகிறது. இது உங்கள் KYC விவரங்கள் குறித்த முக்கியமான தகவல். சரிபார்ப்பிற்காக நான் உங்களை மீண்டும் எப்போது அழைக்கலாம்?"
    },
    {
      "role": "user",
      "en_text": "அவர்கள் ஏற்கனவே இரண்டு முறை அழைத்தனர். இப்போது இணைப்பைத் துண்டியுங்கள்."
    },
    {
      "role": "agent",
      "en_text": "உங்கள் கவலை எனக்குப் புரிகிறது. இருப்பினும், இந்த அழைப்பு குறிப்பாக உங்கள் KYC விவரங்களை புதுப்பிப்பதற்காகவே,"
    }
  ]
}

{
  "interaction_transcript": [
    {
      "role": "agent",
      "en_text": "નમસ્તે, હું SMFG INDIA CREDIT COMPANY માંથી વાણી બોલી રહી છું. શું હું શેખ મુમતાજબાનું મોહમ્મદજાવિદ સાથે વાત કરી રહી છું?"
    }
  ]
}

{
  "interaction_transcript": [
    {"role": "agent", "en_text": "హలో, నేను రాధ, నేను కట్ట వెంకన్నతో మాట్లాడుతున్నానా?"},
    {"role": "user", "en_text": "నేను కట్ట వెంకన్నతో మాట్లాడుతున్నాను."},
    {"role": "agent", "en_text": "కట్ట వెంకన్న, SMFG ఇండియా క్రెడిట్ కంపెనీ నుండి మీకు ₹54,793 బకాయి ఉంది. ఈ రోజు క్లియర్ చేయడం సాధ్యమవుతుందా?"},
    {"role": "user", "en_text": "నేను చేస్తాను, నేను చేస్తాను."},
    {"role": "agent", "en_text": "అద్భుతం! కాబట్టి, నిర్ధారించడానికి, మీరు ఈరోజు, శుక్రవారం ₹54,793 మొత్తాన్ని క్లియర్ చేస్తారు, అంతేనా?"}
  ]
}

{
  "interaction_transcript": [
    {"role": "agent", "en_text": "नमस्ते। मैं एसएमएफजी इंडिया क्रेडिट कंपनी से वाणी बोल रही हूँ। क्या मेरी बात रमेश कुमारी से हो रही है?"}
  ]
}

{
  "interaction_transcript": [
    {
      "role": "agent",
      "en_text": "હેલો. હું SMFG ઇન્ડિયા ક્રેડિટ કંપનીમાંથી વાણી વાત કરી રહી છું. શું હું મહેશ ભાનુભાઈ વડાડોરિયા સાથે વાત કરી રહી છું?"
    }
  ]
}

{
  "interaction_transcript": [
    {"role": "agent", "en_text": "हेलो, मैं राधा हूँ, क्या मैं सुमेरा फातिमा से बात कर रही हूँ?"},
    {"role": "user", "en_text": "धन्यवाद, कृपया लाइन पर बने रहें।"},
    {"role": "agent", "en_text": "ठीक है, मैं लाइन पर आपका इंतजार करुंगी।"},
    {"role": "agent", "en_text": "क्या आप कॉल पर हैं?"},
    {"role": "user", "en_text": "मुझे माफ करना, यह व्यक्ति उपलब्ध नहीं है। यदि आप कोई अतिरिक्त संदेश छोड़ना चाहते हैं, तो कृपया टोन के बाद जवाब दें।"},
    {"role": "agent", "en_text": "आपको वापस कॉल करने का अच्छा समय कब होगा?"},
    {"role": "agent", "en_text": "क्या आप कॉल पर हैं?"},
    {"role": "agent", "en_text": "आपके समय के लिए धन्यवाद"}
  ]
}

{
  "interaction_transcript": [
    {"role": "agent", "en_text": "नमस्ते। मैं SMFG INDIA CREDIT COMPANY से राधा बोल रही हूँ। क्या मैं ANUJ SAINI से बात कर रही हूँ?"},
    {"role": "user", "en_text": "कृपया अपना संदेश रिकॉर्ड करें। जब आप रिकॉर्डिंग समाप्त कर लें, तो आप कॉल काट सकते हैं।"},
    {"role": "agent", "en_text": "मैं SMFG INDIA CREDIT COMPANY से बोल रही हूँ। क्या मैं यह पुष्टि कर सकती हूँ कि मैं ANUJ SAINI से बात कर रही हूँ?"},
    {"role": "agent", "en_text": "मुझे खेद है, आपकी आवाज स्पष्ट नहीं है। क्या आप फिर से कह सकते हैं?"},
    {"role": "agent", "en_text": "आपका कीमती समय देने के लिए धन्यवाद। आपका दिन शुभ हो।"}
  ]
}

{
  "app_id" : "ECS-SMFG-NE-f1a09ab8-5de1",
  "app_version" : 2,
  "interaction_transcript" : [ {
    "role" : "agent",
    "en_text" : "नमस्ते। मैं SMFG INDIA CREDIT COMPANY से राधा बोल रही हूँ। क्या मैं चिंतामणि जी से बात कर रही हूँ?"
  }, {
    "role" : "user",
    "en_text" : "हाँ।"
